files.content:
:root {
  --bg: #0c0e0f;
  --surface: #171a1d;
  --surface-2: #202529;
  --surface-3: #272022;
  --line: #30383d;
  --text: #e6edf0;
  --muted: #91a0a8;
  --green: #29c66f;
  --amber: #e2b84f;
  --red: #ee5f5f;
  --cyan: #49bfd4;
  --blue: #6fa8ff;
  --rose: #d36a8b;
  --violet: #9581d9;
  --shadow: rgba(0, 0, 0, 0.32);
  --font-ui: "Aptos", "Segoe UI Variable Text", "Segoe UI", system-ui, -apple-system, BlinkMacSystemFont, sans-serif;
  --font-display: "Aptos Display", "Segoe UI Variable Display", "Segoe UI", system-ui, -apple-system, BlinkMacSystemFont, sans-serif;
  --font-mono: "Cascadia Mono", "Cascadia Code", "Roboto Mono", "SFMono-Regular", Consolas, monospace;
}

* {
  box-sizing: border-box;
}

body {
  margin: 0;
  background:
    linear-gradient(180deg, rgba(255,255,255,0.032), transparent 150px),
    linear-gradient(120deg, rgba(73, 191, 212, 0.07), transparent 34%, rgba(226,184,79,0.04) 72%, transparent),
    #05070a;
  color: var(--text);
  font-family: var(--font-ui);
  letter-spacing: 0;
}

html.graph-dragging-page-lock,
html.graph-dragging-page-lock body {
  overflow: hidden;
}

button {
  border: 1px solid var(--line);
  border-radius: 8px;
  background: #232a2f;
  color: var(--text);
  cursor: pointer;
  font: inherit;
  min-height: 40px;
  padding: 9px 12px;
}

button:hover:not(:disabled) {
  border-color: var(--cyan);
  background: #263238;
}

button:disabled {
  color: #6e7a81;
  cursor: not-allowed;
  background: #1a1f22;
}

.app-shell {
  display: grid;
  grid-template-columns: 250px minmax(0, 1fr);
  min-height: 100vh;
  width: 100%;
  overflow-x: hidden;
}

.pipeline-only {
  width: 100%;
  min-height: 100vh;
  margin: 0;
  padding: 24px;
  display: grid;
  align-content: start;
  gap: 14px;
}

.pipeline-topbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 18px;
  padding-right: 244px;
}

.pipeline-topbar h1 {
  margin-top: 6px;
}

.eyebrow {
  color: var(--cyan);
  font-size: 12px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0;
}

.pipeline-status {
  display: flex;
  align-items: center;
  gap: 10px;
  flex-wrap: wrap;
  justify-content: flex-end;
}

.sidebar {
  border-right: 1px solid var(--line);
  background:
    linear-gradient(180deg, rgba(73, 191, 212, 0.08), transparent 32%),
    #121517;
  padding: 20px 16px;
  position: sticky;
  top: 0;
  height: 100vh;
}

.brand {
  display: flex;
  align-items: center;
  gap: 12px;
  margin-bottom: 28px;
}

.brand-mark {
  width: 34px;
  height: 34px;
  border-radius: 8px;
  background:
    linear-gradient(135deg, rgba(73, 191, 212, 0.95), rgba(41, 198, 111, 0.95)),
    #1b262b;
  box-shadow: 0 0 24px rgba(73, 191, 212, 0.22);
  position: relative;
}

.brand-mark::after {
  content: "";
  position: absolute;
  inset: 8px;
  border: 2px solid rgba(12, 14, 15, 0.7);
  border-radius: 4px;
}

.brand strong,
.brand small {
  display: block;
}

.brand small,
.subtle,
small {
  color: var(--muted);
}

.nav {
  display: grid;
  gap: 7px;
}

.nav a {
  color: var(--muted);
  text-decoration: none;
  padding: 10px 12px;
  border-radius: 8px;
}

.nav a:hover,
.nav a.active {
  color: var(--text);
  background: #20272b;
}

.sidebar-note {
  position: absolute;
  bottom: 20px;
  display: flex;
  align-items: center;
  gap: 8px;
  color: var(--muted);
}

.dot {
  width: 9px;
  height: 9px;
  border-radius: 50%;
  background: var(--muted);
}

.dot.green {
  background: var(--green);
}

.main {
  padding: 24px;
  display: grid;
  gap: 18px;
  min-width: 0;
  width: min(100%, calc(100vw - 250px));
}

.main > * {
  width: 100%;
  min-width: 0;
  max-width: 100%;
}

.topbar {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  gap: 16px;
}

h1,
h2,
p {
  margin: 0;
}

h1 {
  font-size: 34px;
  line-height: 1.2;
  font-weight: 800;
}

h2 {
  font-size: 15px;
}

.topbar p {
  color: var(--muted);
  margin-top: 6px;
}

.topbar-actions {
  display: flex;
  align-items: center;
  gap: 10px;
  flex-wrap: wrap;
  justify-content: flex-end;
}

.pill,
.status-token {
  border: 1px solid var(--line);
  border-radius: 999px;
  color: var(--muted);
  padding: 7px 10px;
  font-size: 12px;
  white-space: nowrap;
}

.mission-strip {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 10px;
}

.mission-cell {
  min-height: 96px;
  border: 1px solid var(--line);
  border-radius: 8px;
  background:
    linear-gradient(180deg, rgba(255,255,255,0.035), transparent),
    #171b1e;
  padding: 13px;
  position: relative;
  overflow: hidden;
}

.mission-cell::before {
  content: "";
  position: absolute;
  left: 0;
  right: 0;
  top: 0;
  height: 3px;
  background: linear-gradient(90deg, var(--cyan), var(--green), var(--amber), var(--rose));
}

.mission-cell small,
.mission-cell strong,
.mission-cell span {
  display: block;
}

.mission-cell strong {
  margin-top: 12px;
  font-size: 18px;
}

.mission-cell span {
  margin-top: 7px;
  color: var(--muted);
  font-size: 13px;
}

.status-token.ok {
  color: var(--green);
  border-color: rgba(41, 198, 111, 0.36);
}

.status-token.warn {
  color: var(--amber);
  border-color: rgba(226, 184, 79, 0.38);
}

.status-token.bad {
  color: var(--red);
  border-color: rgba(238, 95, 95, 0.38);
}

.grid {
  display: grid;
  gap: 18px;
}

.command-grid {
  grid-template-columns: minmax(0, 2fr) minmax(0, 1fr) minmax(0, 1fr);
}

.two-col {
  grid-template-columns: minmax(280px, 0.7fr) minmax(360px, 1.3fr);
}

.panel {
  background:
    linear-gradient(180deg, rgba(255, 255, 255, 0.035), rgba(255, 255, 255, 0.006)),
    var(--surface);
  border: 1px solid var(--line);
  border-radius: 8px;
  box-shadow: 0 12px 34px var(--shadow);
  padding: 16px;
}

.status-panel {
  background:
    linear-gradient(135deg, rgba(73, 191, 212, 0.12), transparent 42%),
    linear-gradient(180deg, rgba(255, 255, 255, 0.04), rgba(255, 255, 255, 0.006)),
    var(--surface);
  grid-column: span 2;
}

.panel-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  margin-bottom: 14px;
}

.metric-grid {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 10px;
}

.metric,
.risk-card,
.run-card,
.shard-card,
.proof-card {
  background:
    linear-gradient(180deg, rgba(255,255,255,0.03), transparent),
    var(--surface-2);
  border: 1px solid var(--line);
  border-radius: 8px;
  padding: 12px;
}

.metric strong,
.metric small {
  display: block;
}

.metric strong {
  margin-top: 8px;
  font-size: 18px;
}

.signal-panel {
  display: grid;
  grid-template-rows: auto 1fr auto;
}

.signal-field {
  min-height: 150px;
  border: 1px solid var(--line);
  border-radius: 8px;
  background:
    linear-gradient(90deg, rgba(255,255,255,0.035) 1px, transparent 1px),
    linear-gradient(rgba(255,255,255,0.035) 1px, transparent 1px),
    #101417;
  background-size: 22px 22px;
  position: relative;
  overflow: hidden;
}

.signal-field::before,
.signal-field::after {
  content: "";
  position: absolute;
  inset: 0;
  background:
    linear-gradient(110deg, transparent 0 24%, rgba(73, 191, 212, 0.18) 25%, transparent 31% 100%);
  transform: translateX(-60%);
  animation: sweep 5.2s ease-in-out infinite;
}

.signal-field::after {
  background:
    linear-gradient(70deg, transparent 0 62%, rgba(226, 184, 79, 0.16) 63%, transparent 69% 100%);
  animation-delay: 1.8s;
}

.signal-field span {
  position: absolute;
  left: calc(12% + var(--i) * 10%);
  bottom: 18px;
  width: 6px;
  height: calc(28px + var(--i) * 9px);
  border-radius: 999px;
  background: linear-gradient(180deg, var(--green), var(--cyan));
  opacity: 0.78;
  animation: bars 1.6s ease-in-out infinite alternate;
  animation-delay: calc(var(--i) * 110ms);
}

.signal-caption {
  display: flex;
  justify-content: space-between;
  gap: 10px;
  margin-top: 10px;
  color: var(--muted);
}

.signal-caption strong {
  color: var(--text);
}

@keyframes sweep {
  0%, 20% {
    transform: translateX(-70%);
  }
  65%, 100% {
    transform: translateX(70%);
  }
}

@keyframes bars {
  from {
    transform: scaleY(0.72);
    filter: saturate(0.85);
  }
  to {
    transform: scaleY(1);
    filter: saturate(1.18);
  }
}

.blocker-strip {
  margin-top: 12px;
  border: 1px solid rgba(226, 184, 79, 0.28);
  background: rgba(226, 184, 79, 0.08);
  border-radius: 8px;
  padding: 10px 12px;
  display: flex;
  justify-content: space-between;
  gap: 10px;
}

.blocker-strip span {
  color: var(--muted);
}

.process-list {
  display: grid;
  gap: 8px;
}

.process-row {
  display: flex;
  justify-content: space-between;
  border: 1px solid var(--line);
  border-radius: 8px;
  padding: 9px 10px;
  background: #171b1e;
}

.button-grid,
.diagnostic-buttons {
  display: grid;
  gap: 8px;
}

.button-grid {
  grid-template-columns: repeat(2, minmax(0, 1fr));
}

.danger-zone {
  border-top: 1px solid var(--line);
  margin-top: 12px;
  padding-top: 12px;
  display: grid;
  gap: 8px;
}

.pipeline-panel {
  overflow: visible;
  background: transparent;
  border: 0;
  border-radius: 0;
  box-shadow: none;
  padding: 0;
  min-width: 0;
  max-width: 100%;
  width: 100%;
}

.pipeline-focus {
  margin-top: 0;
}

.pipeline-focus .system-map {
  min-height: min(620px, calc(100vh - 230px));
}

.pipeline-panel .panel-head {
  padding-right: 244px;
}

.graph-workspace {
  display: grid;
  grid-template-columns: minmax(0, 1fr) 304px;
  gap: 12px;
  align-items: start;
  min-width: 0;
  overflow: visible;
}

.graph-window {
  min-width: 0;
  border: 1px solid rgba(255,255,255,0.1);
  border-radius: 8px;
  background:
    linear-gradient(180deg, rgba(255,255,255,0.055), transparent 82px),
    rgba(12, 15, 17, 0.9);
  box-shadow: 0 24px 62px rgba(0,0,0,0.3);
  overflow: hidden;
}

.graph-window-head {
  min-height: 52px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  border-bottom: 1px solid rgba(255,255,255,0.08);
  background: rgba(14, 18, 20, 0.86);
  padding: 8px 10px 8px 12px;
}

.graph-window-title {
  min-width: 0;
  display: grid;
  gap: 2px;
}

.graph-window-title small {
  color: var(--cyan);
  font-size: 11px;
  font-weight: 850;
  text-transform: uppercase;
}

.graph-window-title strong {
  color: var(--text);
  font-size: 13px;
  white-space: nowrap;
}

.graph-window-controls {
  display: flex;
  align-items: center;
  gap: 6px;
  flex: 0 0 auto;
}

.graph-icon-button {
  width: 34px;
  height: 34px;
  min-height: 34px;
  display: inline-grid;
  place-items: center;
  border-radius: 8px;
  padding: 0;
  font-size: 17px;
  font-weight: 800;
}

.graph-zoom-readout {
  min-width: 48px;
  color: var(--muted);
  font-size: 12px;
  font-weight: 800;
  text-align: center;
}

.graph-viewport {
  position: relative;
  height: min(680px, calc(100vh - 214px));
  min-height: 520px;
  overflow: hidden;
  background:
    linear-gradient(90deg, rgba(255,255,255,0.035) 1px, transparent 1px),
    linear-gradient(rgba(255,255,255,0.035) 1px, transparent 1px),
    #090d0f;
  background-size: 32px 32px, 32px 32px, auto;
  cursor: grab;
  touch-action: none;
  overscroll-behavior: contain;
  user-select: none;
  outline: none;
}

.graph-viewport.dragging {
  cursor: grabbing;
}

.graph-viewport:focus-visible {
  box-shadow: inset 0 0 0 2px rgba(73,191,212,0.58);
}

.graph-board {
  --board-grid: rgba(255,255,255,0.045);
  position: absolute;
  left: 0;
  top: 0;
  width: 1680px;
  height: 780px;
  overflow: hidden;
  border: 0;
  border-radius: 0;
  background:
    linear-gradient(90deg, var(--board-grid) 1px, transparent 1px),
    linear-gradient(var(--board-grid) 1px, transparent 1px),
    linear-gradient(180deg, rgba(255,255,255,0.045), transparent 18%, rgba(0,0,0,0.18)),
    linear-gradient(115deg, rgba(73,191,212,0.08), transparent 34%, rgba(41,198,111,0.045) 52%, rgba(226,184,79,0.06) 76%, rgba(238,95,95,0.035)),
    #0b0e10;
  background-size: 40px 40px, 40px 40px, auto, auto, auto;
  box-shadow: none;
  transform-origin: 0 0;
  will-change: transform;
}

.graph-board::before {
  content: "";
  position: absolute;
  inset: 0;
  background:
    linear-gradient(90deg, transparent 0 9%, rgba(73,191,212,0.08) 9% 36%, transparent 36% 39%, rgba(41,198,111,0.06) 39% 58%, transparent 58% 61%, rgba(226,184,79,0.07) 61% 86%, transparent 86%),
    linear-gradient(180deg, transparent 0 22%, rgba(255,255,255,0.035) 22% 23%, transparent 23% 50%, rgba(255,255,255,0.035) 50% 51%, transparent 51% 78%, rgba(255,255,255,0.035) 78% 79%, transparent 79%);
  pointer-events: none;
}

.lane-layer,
.edge-layer,
.node-layer {
  position: absolute;
  inset: 0;
}

.lane-layer {
  pointer-events: none;
}

.lane-label {
  position: absolute;
  left: 12px;
  transform: translateY(-50%);
  color: rgba(145,160,168,0.5);
  font-size: 10px;
  font-weight: 800;
  text-transform: uppercase;
}

.edge-layer {
  width: 100%;
  height: 100%;
  overflow: visible;
}

.edge {
  --edge-color: var(--muted);
  --edge-weight: 1;
  color: var(--edge-color);
}

.edge.tone-good { --edge-color: var(--green); }
.edge.tone-warm { --edge-color: var(--amber); }
.edge.tone-active { --edge-color: var(--cyan); }
.edge.tone-idle { --edge-color: var(--blue); }
.edge.tone-blocked { --edge-color: var(--red); }

.edge-line,
.edge-pulse {
  fill: none;
  vector-effect: non-scaling-stroke;
  stroke-linecap: round;
  stroke-linejoin: round;
}

.edge-line {
  stroke: rgba(145,160,168,0.2);
  stroke-width: calc(1.2px + var(--edge-weight) * 0.55px);
}

.edge-pulse {
  stroke: var(--edge-color);
  stroke-width: calc(2px + var(--edge-weight) * 0.8px);
  stroke-dasharray: 10 54;
  opacity: 0;
  filter: drop-shadow(0 0 8px var(--edge-color));
  animation: edgePulse var(--edge-speed, 1.8s) linear infinite;
}

.edge.active .edge-line {
  stroke: var(--edge-color);
  opacity: 0.42;
}

.edge.active .edge-pulse {
  opacity: 0.92;
}

.edge.blocked .edge-line {
  stroke: var(--red);
  stroke-dasharray: 8 9;
  opacity: 0.5;
}

.edge.blocked .edge-pulse {
  stroke: var(--red);
  stroke-dasharray: 2 16;
  opacity: 0.38;
}

.edge-arrow {
  fill: rgba(145,160,168,0.42);
}

.edge-label {
  fill: rgba(230,237,240,0.82);
  stroke: rgba(11,14,16,0.82);
  stroke-width: 4px;
  paint-order: stroke;
  font-size: 12px;
  font-weight: 750;
  opacity: 0;
  pointer-events: none;
}

.edge.active .edge-label,
.edge.blocked .edge-label {
  opacity: 1;
}

@keyframes edgePulse {
  to {
    stroke-dashoffset: -128;
  }
}

.node-layer {
  pointer-events: none;
}

.graph-node {
  --tone-color: var(--muted);
  position: absolute;
  transform: translate(-50%, -50%);
  width: 136px;
  min-height: 62px;
  display: flex;
  align-items: center;
  gap: 8px;
  border: 1px solid rgba(255,255,255,0.1);
  border-radius: 8px;
  background: rgba(17, 21, 23, 0.92);
  box-shadow: 0 12px 26px rgba(0,0,0,0.24);
  padding: 8px;
  color: var(--text);
  pointer-events: auto;
  text-align: left;
  transition: border-color 140ms ease, background 140ms ease, opacity 140ms ease, transform 140ms ease;
}

.graph-node:hover,
.graph-node:focus-visible {
  border-color: rgba(73,191,212,0.72);
  outline: none;
  transform: translate(-50%, -50%) translateY(-2px);
}

.graph-node.selected {
  border-color: color-mix(in srgb, var(--tone-color), white 28%);
  box-shadow:
    0 12px 26px rgba(0,0,0,0.24),
    0 0 0 2px color-mix(in srgb, var(--tone-color), transparent 56%),
    0 0 24px color-mix(in srgb, var(--tone-color), transparent 78%);
}

.graph-node.tone-good { --tone-color: var(--green); }
.graph-node.tone-warm { --tone-color: var(--amber); }
.graph-node.tone-active { --tone-color: var(--cyan); }
.graph-node.tone-idle { --tone-color: var(--blue); }
.graph-node.tone-blocked { --tone-color: var(--red); }
.graph-node.tone-off { --tone-color: #576269; }

.node-dot {
  width: 14px;
  height: 14px;
  flex: 0 0 auto;
  border-radius: 50%;
  background: var(--tone-color);
  box-shadow: 0 0 16px color-mix(in srgb, var(--tone-color), transparent 32%);
}

.node-copy {
  min-width: 0;
  display: grid;
  gap: 2px;
}

.graph-node small,
.graph-node strong,
.graph-node em {
  display: block;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.graph-node small {
  color: var(--muted);
  font-size: 10px;
  font-weight: 800;
  text-transform: uppercase;
}

.graph-node strong {
  color: var(--text);
  font-size: 13px;
  line-height: 1.05;
}

.graph-node em {
  color: rgba(230,237,240,0.74);
  font-size: 11px;
  font-style: normal;
}

.graph-node.active {
  border-color: color-mix(in srgb, var(--tone-color), white 12%);
  background:
    linear-gradient(180deg, color-mix(in srgb, var(--tone-color), transparent 88%), transparent),
    rgba(18, 24, 26, 0.96);
  animation: graphNodePulse 2.2s ease-in-out infinite;
}

.graph-node.active .node-dot {
  animation: graphDotPulse 1.25s ease-in-out infinite;
}

.graph-node.off {
  opacity: 0.58;
}

.graph-node.off .node-dot {
  box-shadow: none;
}

.graph-node.ready {
  opacity: 0.72;
  border-color: color-mix(in srgb, var(--tone-color), transparent 72%);
}

.graph-node.ready .node-dot {
  opacity: 0.58;
  box-shadow: none;
}

.graph-node.blocked {
  border-color: rgba(238,95,95,0.5);
  border-style: dashed;
  background: rgba(38, 18, 20, 0.92);
}

@keyframes graphNodePulse {
  50% {
    box-shadow: 0 12px 26px rgba(0,0,0,0.24), 0 0 22px color-mix(in srgb, var(--tone-color), transparent 72%);
  }
}

@keyframes graphDotPulse {
  50% {
    transform: scale(1.22);
  }
}

.graph-inspector {
  display: grid;
  gap: 10px;
  min-width: 0;
}

.graph-stat {
  border: 1px solid rgba(255,255,255,0.09);
  border-radius: 8px;
  background:
    linear-gradient(160deg, rgba(73,191,212,0.08), transparent 42%, rgba(226,184,79,0.055)),
    rgba(15, 19, 21, 0.88);
  padding: 12px;
}

.graph-stat small,
.graph-stat strong,
.graph-stat span {
  display: block;
}

.graph-stat small {
  color: var(--cyan);
  font-size: 11px;
  font-weight: 850;
  text-transform: uppercase;
}

.graph-stat strong {
  margin-top: 8px;
  font-size: 18px;
}

.graph-stat span {
  margin-top: 6px;
  color: var(--muted);
  font-size: 12px;
}

.node-inspector {
  --inspector-color: var(--muted);
  border-color: color-mix(in srgb, var(--inspector-color), transparent 68%);
  background:
    linear-gradient(145deg, color-mix(in srgb, var(--inspector-color), transparent 90%), transparent 44%),
