.node-inspector.tone-good { --inspector-color: var(--green); }
.node-inspector.tone-warm { --inspector-color: var(--amber); }
.node-inspector.tone-active { --inspector-color: var(--cyan); }
.node-inspector.tone-idle { --inspector-color: var(--blue); }
.node-inspector.tone-blocked { --inspector-color: var(--red); }
.node-inspector.tone-off { --inspector-color: #66727a; }

.node-inspector.active {
