  background:
    linear-gradient(90deg, rgba(255,255,255,0.018) 1px, transparent 1px),
    linear-gradient(rgba(255,255,255,0.014) 1px, transparent 1px),
    linear-gradient(180deg, rgba(255,255,255,0.04), transparent 22%, rgba(0,0,0,0.18)),
    #05070a;
  background-size: 56px 56px, 56px 56px, auto, auto;
}

.graph-board {
  --board-grid: rgba(255,255,255,0.015);
  background:
    linear-gradient(90deg, var(--board-grid) 1px, transparent 1px),
    linear-gradient(var(--board-grid) 1px, transparent 1px),
    linear-gradient(180deg, rgba(255,255,255,0.055), transparent 90px, rgba(0,0,0,0.18)),
    linear-gradient(118deg, rgba(73,191,212,0.055), transparent 36%, rgba(226,184,79,0.032) 76%, transparent),
    #05070a;
  background-size: 64px 64px, 64px 64px, auto, auto, auto;
}

.graph-board::before {
  background:
    linear-gradient(180deg, rgba(255,255,255,0.04), transparent 68px, transparent 90%, rgba(0,0,0,0.22)),
    linear-gradient(90deg, rgba(73,191,212,0.045), transparent 18%, transparent 82%, rgba(226,184,79,0.028));
}

.lane-separator {
  --lane-color: rgba(145,160,168,0.34);
  position: absolute;
  top: 42px;
  bottom: 34px;
  width: 1px;
  transform: translateX(-50%);
  background: linear-gradient(180deg, var(--lane-color), rgba(255,255,255,0.035) 18%, rgba(255,255,255,0.025) 82%, transparent);
}

.lane-separator::before {
  content: "";
  position: absolute;
  top: 0;
  left: -18px;
  width: 36px;
  height: 2px;
  background: var(--lane-color);
  box-shadow: 0 0 14px color-mix(in srgb, var(--lane-color), transparent 54%);
}

.lane-label {
  --lane-color: rgba(145,160,168,0.42);
  top: 23px;
  transform: translateX(-50%);
  color: rgba(192,205,211,0.62);
  font-family: "JetBrains Mono", "IBM Plex Mono", ui-monospace, SFMono-Regular, Consolas, monospace;
  font-size: 10px;
  font-weight: 760;
  text-transform: uppercase;
}

.lane-separator.tone-active,
.lane-label.tone-active { --lane-color: rgba(73,191,212,0.62); }
.lane-separator.tone-good,
.lane-label.tone-good { --lane-color: rgba(41,198,111,0.54); }
.lane-separator.tone-warm,
.lane-label.tone-warm { --lane-color: rgba(226,184,79,0.62); }
.lane-separator.tone-idle,
.lane-label.tone-idle { --lane-color: rgba(111,168,255,0.45); }
.lane-separator.tone-blocked,
.lane-label.tone-blocked { --lane-color: rgba(238,95,95,0.5); }

.edge {
  --edge-color: rgba(145,160,168,0.72);
  transition: opacity 140ms ease;
}

.edge.tone-good { --edge-color: var(--cyan); }
.edge.tone-warm { --edge-color: var(--amber); }
.edge.tone-active { --edge-color: var(--cyan); }
.edge.tone-idle { --edge-color: rgba(111,168,255,0.72); }
.edge.tone-blocked { --edge-color: var(--red); }

.edge-line {
  stroke: rgba(145,160,168,0.22);
  stroke-width: calc(1.4px + var(--edge-weight) * 0.46px);
  stroke-dasharray: 7 14;
  opacity: 0.72;
}

.edge-pulse {
  stroke: var(--edge-color);
  stroke-width: calc(2px + var(--edge-weight) * 0.72px);
  stroke-dasharray: 16 72;
  opacity: 0;
  filter: drop-shadow(0 0 10px color-mix(in srgb, var(--edge-color), transparent 24%));
}

.edge.active .edge-line {
  stroke: var(--edge-color);
  stroke-dasharray: none;
  opacity: 0.52;
}

.edge.active .edge-pulse {
  opacity: 0.95;
}

.edge.blocked .edge-line {
  stroke: var(--red);
  stroke-dasharray: 5 10;
  opacity: 0.62;
}

.edge.blocked .edge-pulse {
  stroke: var(--red);
  stroke-dasharray: 2 18;
  opacity: 0.32;
}

.edge.selected .edge-line,
.edge.hovered .edge-line {
  opacity: 0.92;
  stroke-width: calc(2px + var(--edge-weight) * 0.62px);
}

.edge.selected .edge-pulse,
.edge.hovered .edge-pulse {
  opacity: 1;
}

.edge.dimmed {
  opacity: 0.16;
}

.edge-arrow {
  fill: rgba(145,160,168,0.48);
}

.edge.active .edge-arrow,
.edge.selected .edge-arrow,
.edge.hovered .edge-arrow {
  fill: var(--edge-color);
}

.edge-label {
  fill: rgba(232,242,246,0.88);
  stroke: rgba(5,7,10,0.9);
  font-family: "JetBrains Mono", "IBM Plex Mono", ui-monospace, SFMono-Regular, Consolas, monospace;
  font-size: 11px;
  font-weight: 680;
}

.edge.active .edge-label,
.edge.blocked .edge-label,
.edge.selected .edge-label,
.edge.hovered .edge-label {
  opacity: 0.96;
}

.graph-node {
  --tone-color: rgba(145,160,168,0.72);
  width: 178px;
  min-height: 86px;
  display: block;
  border-color: rgba(255,255,255,0.12);
  border-radius: 8px;
  background:
    linear-gradient(180deg, rgba(255,255,255,0.07), transparent 52%),
    rgba(12, 17, 20, 0.94);
  box-shadow:
    0 18px 34px rgba(0,0,0,0.34),
    inset 0 1px 0 rgba(255,255,255,0.05);
  padding: 11px 12px 10px;
  transition: border-color 140ms ease, background 140ms ease, opacity 140ms ease, transform 140ms ease, box-shadow 140ms ease, filter 140ms ease;
  backdrop-filter: blur(14px);
}

.graph-node:hover,
.graph-node:focus-visible {
  border-color: rgba(73,191,212,0.74);
  box-shadow:
    0 20px 38px rgba(0,0,0,0.38),
    0 0 0 1px rgba(73,191,212,0.18),
    0 0 28px rgba(73,191,212,0.14);
}

.graph-node.selected {
  border-color: color-mix(in srgb, var(--tone-color), white 22%);
  box-shadow:
    0 22px 44px rgba(0,0,0,0.42),
    0 0 0 2px color-mix(in srgb, var(--tone-color), transparent 60%),
    0 0 32px color-mix(in srgb, var(--tone-color), transparent 74%);
}

.graph-node.related {
  border-color: color-mix(in srgb, var(--tone-color), white 10%);
}

.graph-node.dimmed {
  opacity: 0.24;
  filter: saturate(0.55);
}

.graph-node.tone-good { --tone-color: var(--green); }
.graph-node.tone-warm { --tone-color: var(--amber); }
.graph-node.tone-active { --tone-color: var(--cyan); }
.graph-node.tone-idle { --tone-color: var(--blue); }
.graph-node.tone-blocked { --tone-color: var(--red); }
.graph-node.tone-off { --tone-color: #657178; }

.node-copy {
  display: grid;
  gap: 5px;
}

.node-status-line {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  min-width: 0;
}

.node-dot {
  width: 11px;
  height: 11px;
  border: 1px solid color-mix(in srgb, var(--tone-color), white 24%);
  background: color-mix(in srgb, var(--tone-color), black 12%);
  box-shadow: 0 0 14px color-mix(in srgb, var(--tone-color), transparent 28%);
}

.node-state-label {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  border: 1px solid color-mix(in srgb, var(--tone-color), transparent 54%);
  border-radius: 8px;
  background: color-mix(in srgb, var(--tone-color), transparent 88%);
  color: color-mix(in srgb, var(--tone-color), white 34%);
  padding: 3px 6px;
  font-family: "JetBrains Mono", "IBM Plex Mono", ui-monospace, SFMono-Regular, Consolas, monospace;
  font-size: 9px;
  font-weight: 760;
}

.graph-node small,
.graph-node strong,
.graph-node em {
  white-space: nowrap;
}

.graph-node strong {
  color: #f4fafc;
  font-size: 14px;
  font-weight: 720;
  line-height: 1.15;
}

.graph-node small {
  color: rgba(145,160,168,0.78);
  font-size: 10px;
  font-weight: 740;
}

.graph-node em {
  color: rgba(230,237,240,0.72);
  font-family: "JetBrains Mono", "IBM Plex Mono", ui-monospace, SFMono-Regular, Consolas, monospace;
  font-size: 11px;
}

.graph-node.active {
  border-color: color-mix(in srgb, var(--tone-color), white 14%);
  background:
    linear-gradient(180deg, color-mix(in srgb, var(--tone-color), transparent 88%), transparent 58%),
    rgba(12, 19, 22, 0.97);
  animation: graphNodePulse 2.4s ease-in-out infinite;
}

.graph-node.active .node-dot {
  animation: graphDotPulse 1.18s ease-in-out infinite;
}

.graph-node.ready {
  opacity: 0.78;
  border-color: color-mix(in srgb, var(--tone-color), transparent 74%);
}

.graph-node.ready .node-dot,
.graph-node.off .node-dot {
  box-shadow: none;
}

.graph-node.off {
  opacity: 0.46;
  border-color: rgba(255,255,255,0.07);
  background: rgba(9, 12, 14, 0.86);
}

.graph-node.blocked {
  border-color: rgba(238,95,95,0.56);
  background:
    linear-gradient(180deg, rgba(238,95,95,0.1), transparent),
    rgba(24, 11, 13, 0.94);
}

@keyframes graphNodePulse {
  50% {
    box-shadow:
      0 20px 42px rgba(0,0,0,0.4),
      0 0 28px color-mix(in srgb, var(--tone-color), transparent 72%);
