  border: 1px solid rgba(255,255,255,0.095);
  border-radius: 8px;
  background: rgba(0,0,0,0.26);
  padding: 2px;
  overflow: hidden;
}

.mode-tab {
  min-height: 24px;
  border: 0;
  border-radius: 6px;
  background: transparent;
  color: rgba(145,160,168,0.92);
  padding: 4px 7px;
  font-size: 11px;
  font-weight: 690;
  white-space: nowrap;
}

.mode-tab:hover:not(:disabled) {
  background: rgba(255,255,255,0.055);
  color: rgba(230,237,240,0.9);
}

.mode-tab.active {
  background: rgba(73,191,212,0.12);
  color: #d7f7fc;
  box-shadow: inset 0 -1px 0 rgba(73,191,212,0.42);
}

.graph-mode-chip {
  padding: 4px 6px;
}

.graph-icon-button {
  width: 26px;
  height: 26px;
  min-height: 26px;
  border-radius: 7px;
  font-size: 14px;
}

.graph-zoom-readout {
  min-width: 38px;
  font-size: 10px;
}

.graph-viewport {
  height: min(640px, calc(100vh - 238px));
  min-height: 500px;
}

.graph-board {
  width: 1420px;
  height: 680px;
}

.graph-node {
  width: 200px;
  min-height: 108px;
  border-radius: 8px;
  padding: 12px 13px 11px;
}

.graph-node strong {
  font-size: 15px;
}

.graph-node small {
  margin-top: 1px;
  font-size: 10px;
  color: rgba(180,193,199,0.74);
}

.graph-node em {
  font-size: 11px;
}

.node-micro {
  display: block;
  min-width: 0;
  margin-top: 2px;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  color: rgba(145,160,168,0.82);
  font-family: "JetBrains Mono", "IBM Plex Mono", ui-monospace, SFMono-Regular, Consolas, monospace;
  font-size: 10px;
}

.graph-node.off {
  opacity: 0.56;
}

.graph-node.ready {
  opacity: 0.68;
}

.graph-node.blocked {
  opacity: 0.62;
}

.edge-packet {
  fill: var(--edge-color);
  opacity: 0;
  filter: drop-shadow(0 0 10px var(--edge-color));
  pointer-events: none;
}

.edge.active .edge-packet,
.edge.hovered .edge-packet,
.edge.selected .edge-packet {
  opacity: 0.96;
}

.edge.active .edge-line {
  filter: drop-shadow(0 0 8px color-mix(in srgb, var(--edge-color), transparent 46%));
}

.graph-inspector {
  gap: 8px;
}

.graph-stat {
  border-color: rgba(255,255,255,0.055);
  background:
    linear-gradient(90deg, rgba(73,191,212,0.05), transparent 48%),
    rgba(3, 5, 7, 0.82);
  box-shadow: none;
  padding: 10px;
}

.graph-stat small {
  color: rgba(145,160,168,0.72);
}

.graph-stat strong {
  margin-top: 5px;
  font-size: 14px;
}

.graph-stat span {
  margin-top: 4px;
  font-size: 11px;
}

.node-inspector {
  border-left: 2px solid var(--inspector-color);
  border-top-color: rgba(255,255,255,0.05);
  border-right-color: rgba(255,255,255,0.035);
  border-bottom-color: rgba(255,255,255,0.035);
  background:
    linear-gradient(90deg, color-mix(in srgb, var(--inspector-color), transparent 88%), transparent 42%),
    rgba(2, 4, 6, 0.9);
}

.node-inspector.active {
  box-shadow: none;
}

.node-inspector p {
  font-size: 11px;
}

.node-flow-chip {
  border-radius: 7px;
  padding: 4px 6px;
  font-size: 9px;
}

.node-metric {
  padding: 6px 7px;
}

.graph-list {
  max-height: 184px;
}

.timeline-strip {
  grid-template-columns: 126px minmax(0, 1fr);
  gap: 8px;
  min-height: 72px;
  padding: 8px 10px;
}

.timeline-head {
  padding-right: 8px;
}

.timeline-head small {
  font-size: 9px;
}

.timeline-head strong {
  font-size: 11px;
}

.event-timeline {
  position: relative;
  gap: 6px;
  scrollbar-width: none;
  -ms-overflow-style: none;
  mask-image: linear-gradient(90deg, transparent, #000 20px, #000 calc(100% - 20px), transparent);
}

.event-timeline::-webkit-scrollbar {
  display: none;
}

.timeline-item {
  flex-basis: 142px;
  min-height: 48px;
  gap: 2px;
  border-left-width: 1px;
  background: rgba(255,255,255,0.028);
  padding: 6px 7px;
}

.timeline-item.latest {
  background:
    linear-gradient(90deg, color-mix(in srgb, var(--timeline-color), transparent 86%), transparent 60%),
    rgba(255,255,255,0.04);
  box-shadow: 0 0 18px color-mix(in srgb, var(--timeline-color), transparent 84%);
}

.timeline-item span {
  font-size: 9px;
}

.timeline-item strong {
  font-size: 11px;
}

.timeline-item em {
  font-size: 10px;
}

.capital-hud {
  top: 16px;
  right: 18px;
  width: 170px;
}

.capital-toggle {
  min-height: 38px;
  border-color: rgba(255,255,255,0.075);
  background:
    linear-gradient(90deg, rgba(226,184,79,0.08), transparent 58%),
    rgba(4, 6, 8, 0.86);
  padding: 7px 8px;
}

.capital-toggle small {
  font-size: 9px;
}

.capital-toggle strong,
.capital-toggle em {
  font-size: 11px;
}

.volume-shell {
  position: relative;
  height: min(720px, calc(100vh - 178px));
  min-height: 520px;
  overflow: hidden;
  border: 1px solid rgba(255,255,255,0.09);
  border-radius: 8px;
  background:
    linear-gradient(90deg, rgba(255,255,255,0.035) 1px, transparent 1px),
    linear-gradient(rgba(255,255,255,0.026) 1px, transparent 1px),
    linear-gradient(135deg, rgba(73,191,212,0.08), rgba(41,198,111,0.035) 38%, rgba(226,184,79,0.055) 68%, rgba(211,106,139,0.04)),
    #0b0e10;
  background-size: 42px 42px, 42px 42px, auto, auto;
  box-shadow: 0 26px 70px rgba(0,0,0,0.3);
}

.volume-shell:active {
  cursor: grabbing;
}

#pipeline-canvas {
  display: block;
  width: 100%;
  height: 100%;
  outline: none;
  cursor: grab;
}

#pipeline-canvas:focus-visible {
  box-shadow: inset 0 0 0 2px rgba(73,191,212,0.55);
}

.volume-glass {
  position: absolute;
  inset: 0;
  pointer-events: none;
  border: 1px solid rgba(255,255,255,0.06);
  background:
    linear-gradient(180deg, rgba(255,255,255,0.07), transparent 18%, transparent 74%, rgba(0,0,0,0.18)),
    linear-gradient(105deg, transparent, rgba(255,255,255,0.05) 48%, transparent 55%);
}

.volume-readout {
  position: absolute;
  left: 14px;
  bottom: 14px;
  display: flex;
  align-items: center;
  gap: 12px;
  max-width: calc(100% - 28px);
  border: 1px solid rgba(255,255,255,0.1);
  border-radius: 8px;
  background: rgba(10, 13, 15, 0.72);
  color: var(--muted);
  padding: 9px 11px;
  backdrop-filter: blur(12px);
}

.volume-readout span,
.volume-readout strong {
  overflow-wrap: anywhere;
}

.volume-readout strong {
  color: var(--text);
  font-size: 12px;
}

.capital-hud {
  position: fixed;
  z-index: 10;
  top: 18px;
  right: 20px;
  width: 224px;
}

.capital-toggle {
  width: 100%;
  min-height: 54px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  border: 1px solid rgba(255,255,255,0.12);
  border-radius: 8px;
  background:
    linear-gradient(160deg, rgba(73,191,212,0.11), transparent 44%, rgba(226,184,79,0.06)),
    rgba(13, 17, 19, 0.88);
  box-shadow: 0 14px 36px rgba(0,0,0,0.28);
  padding: 8px 10px;
  text-align: left;
  backdrop-filter: blur(16px);
}

.capital-toggle:hover {
  border-color: rgba(73,191,212,0.46);
  background:
    linear-gradient(160deg, rgba(73,191,212,0.15), transparent 44%, rgba(226,184,79,0.08)),
    rgba(17, 22, 24, 0.94);
}

.capital-toggle span,
.capital-toggle small,
.capital-toggle strong,
.capital-toggle em {
  min-width: 0;
}

.capital-toggle span {
  display: grid;
  gap: 3px;
}

.capital-toggle small {
  color: var(--cyan);
  font-size: 12px;
  font-weight: 800;
  text-transform: uppercase;
}

.capital-toggle strong {
  color: var(--text);
  font-size: 13px;
  white-space: nowrap;
}

.capital-toggle em {
  color: var(--muted);
  font-size: 12px;
  font-weight: 700;
  font-style: normal;
  white-space: nowrap;
}

.capital-toggle::after {
  content: "";
  width: 8px;
  height: 8px;
  border-right: 2px solid rgba(230,237,240,0.72);
  border-bottom: 2px solid rgba(230,237,240,0.72);
  transform: rotate(45deg) translateY(-2px);
  transition: transform 150ms ease;
}

.capital-hud.open .capital-toggle::after {
  transform: rotate(225deg) translate(-2px, -1px);
}

.capital-dropdown {
  position: absolute;
  top: calc(100% + 8px);
  right: 0;
  width: 304px;
  max-height: calc(100vh - 92px);
  overflow: hidden;
  border: 1px solid rgba(255,255,255,0.11);
  border-radius: 8px;
  background:
    linear-gradient(160deg, rgba(73,191,212,0.09), transparent 36%, rgba(226,184,79,0.065)),
    rgba(13, 17, 19, 0.92);
  box-shadow: 0 22px 54px rgba(0,0,0,0.38);
  backdrop-filter: blur(16px);
  display: none;
  pointer-events: none;
}

.capital-hud.open .capital-dropdown {
  display: block;
  pointer-events: auto;
}

.capital-list {
  max-height: calc(100vh - 110px);
  overflow: auto;
  padding: 4px 0;
}

.capital-item {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  gap: 3px 10px;
  padding: 8px 13px;
  border-top: 1px solid rgba(255,255,255,0.045);
}

.capital-item:first-child {
  border-top: 0;
}

.capital-item span {
  color: var(--muted);
  font-size: 12px;
  min-width: 0;
}

.capital-item strong {
  color: var(--text);
  font-size: 13px;
  text-align: right;
  white-space: nowrap;
}

.capital-item em {
  grid-column: 1 / -1;
  color: rgba(145,160,168,0.72);
  font-size: 11px;
  font-style: normal;
  text-align: right;
}

.capital-item.loading strong {
  color: var(--amber);
}

.map-node em {
  display: block;
  margin-top: 6px;
  color: var(--muted);
  font-size: 12px;
  font-style: normal;
  font-weight: 500;
}

.system-map {
  min-height: 420px;
  border: 1px solid rgba(255,255,255,0.08);
  border-radius: 8px;
  background:
    linear-gradient(90deg, rgba(255,255,255,0.032) 1px, transparent 1px),
    linear-gradient(rgba(255,255,255,0.032) 1px, transparent 1px),
    linear-gradient(145deg, rgba(73,191,212,0.075), transparent 36%, rgba(226,184,79,0.05) 72%, transparent);
  background-size: 38px 38px, 38px 38px, auto;
  position: relative;
  overflow: hidden;
  min-width: 0;
}

.system-map::before {
  content: "";
  position: absolute;
  inset: -80px 0 auto 0;
  height: 180px;
  background: linear-gradient(180deg, rgba(255,255,255,0.06), transparent);
  transform: skewY(-7deg);
  opacity: 0.42;
}

.map-lines {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  display: block;
}

.rail {
  fill: none;
  stroke: rgba(73, 191, 212, 0.34);
  stroke-width: 3;
  stroke-linecap: round;
  stroke-dasharray: 9 13;
  animation: railFlow 13s linear infinite;
}

.rail-b {
  stroke: rgba(41, 198, 111, 0.3);
  stroke-width: 2.5;
  animation-duration: 10s;
}

.rail-c {
  stroke: rgba(226, 184, 79, 0.34);
}

.rail-d {
  stroke: rgba(111, 168, 255, 0.28);
  stroke-width: 2;
  animation-duration: 8.5s;
}

.rail.dotted {
  stroke-dasharray: 4 14;
}

@keyframes railFlow {
  to {
    stroke-dashoffset: -220;
  }
}

.map-spark {
  position: absolute;
  width: 11px;
  height: 11px;
  border-radius: 50%;
  background: var(--cyan);
  box-shadow: 0 0 18px rgba(73,191,212,0.78);
  pointer-events: none;
}

.spark-a {
  animation: mapSparkA 5.2s cubic-bezier(.37,.01,.45,1) infinite;
}

.spark-b {
  width: 9px;
  height: 9px;
  background: var(--green);
  box-shadow: 0 0 16px rgba(41,198,111,0.72);
  animation: mapSparkB 6.1s cubic-bezier(.37,.01,.45,1) infinite;
  animation-delay: 900ms;
}

.spark-c {
  width: 8px;
  height: 8px;
  background: var(--amber);
  box-shadow: 0 0 15px rgba(226,184,79,0.72);
  animation: mapSparkC 4.8s cubic-bezier(.37,.01,.45,1) infinite;
  animation-delay: 1.7s;
}

@keyframes mapSparkA {
  0% { left: 6%; top: 49%; opacity: 0; }
  10% { opacity: 1; }
  32% { left: 32%; top: 22%; }
  58% { left: 58%; top: 50%; }
  84% { left: 82%; top: 20%; opacity: 1; }
  100% { left: 92%; top: 49%; opacity: 0; }
}

@keyframes mapSparkB {
  0% { left: 18%; top: 26%; opacity: 0; }
  15% { opacity: 1; }
  48% { left: 50%; top: 58%; }
  78% { left: 76%; top: 45%; opacity: 1; }
  100% { left: 94%; top: 62%; opacity: 0; }
}

@keyframes mapSparkC {
  0% { left: 34%; top: 49%; opacity: 0; }
  18% { opacity: 1; }
  52% { left: 46%; top: 25%; }
  100% { left: 58%; top: 48%; opacity: 0; }
}

.map-node {
  position: absolute;
  min-width: 108px;
  min-height: 66px;
  padding: 10px 12px;
  text-align: left;
  background: rgba(21, 26, 29, 0.92);
  box-shadow: 0 12px 26px rgba(0,0,0,0.27);
}

.map-node::after {
  content: "";
  position: absolute;
  inset: 6px;
  border: 1px solid rgba(255,255,255,0.055);
  border-radius: 5px;
  pointer-events: none;
}

.map-node small,
.map-node strong {
  display: block;
}

.map-node small {
  font-size: 11px;
}

.map-node strong {
  margin-top: 5px;
  font-size: 16px;
}

.map-node.good {
  border-color: rgba(41,198,111,0.5);
}

.map-node.warm,
.map-node.active {
  border-color: rgba(226,184,79,0.5);
}

.map-node.idle {
  color: var(--muted);
}

.map-node.blocked {
  border-style: dashed;
  color: #d5b5b5;
  border-color: rgba(238,95,95,0.42);
}

.map-node.active {
  animation: nodeBreathe 2.8s ease-in-out infinite;
}

.map-node:hover {
  transform: translateY(-2px);
  border-color: var(--cyan);
}

@keyframes nodeBreathe {
  0%, 100% {
    box-shadow: 0 12px 26px rgba(0,0,0,0.27), 0 0 0 rgba(226,184,79,0);
  }
  50% {
    box-shadow: 0 12px 26px rgba(0,0,0,0.27), 0 0 26px rgba(226,184,79,0.2);
  }
}

.n-agave { left: 4%; top: 44%; }
.n-afxdp { left: 14%; top: 17%; }
.n-decode { left: 25%; top: 42%; }
.n-state { left: 35%; top: 62%; }
.n-quote { left: 45%; top: 23%; }
.n-owner { left: 56%; top: 42%; }
.n-pm { left: 67%; top: 62%; }
.n-tpu { left: 79%; top: 24%; }
.n-public { left: 83%; top: 61%; }
.n-reconcile { right: 4%; top: 43%; }
.n-jito { right: 6%; top: 9%; }
.n-inventory { left: 47%; bottom: 8%; }

.pipeline-details,
.inventory-grid,
.shard-grid {
  margin-top: 12px;
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 10px;
}

.compact-details {
  grid-template-columns: minmax(180px, 1fr) minmax(120px, 0.55fr) minmax(220px, 1.1fr);
}

.proof-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 10px;
}

.proof-card {
  border-left: 4px solid var(--green);
}

.proof-card.amber {
  border-left-color: var(--amber);
}

.proof-card.red {
  border-left-color: var(--red);
}

.proof-card small,
.proof-card strong,
.proof-card span {
  display: block;
}

.proof-card strong {
  margin-top: 8px;
  font-size: 17px;
}

.proof-card span {
  color: var(--muted);
  margin-top: 6px;
}

.pipeline-details div {
  background: #15191c;
  border: 1px solid var(--line);
  border-radius: 8px;
  padding: 10px;
}

.pipeline-details strong,
.risk-card strong,
.risk-card span {
  display: block;
  margin-top: 6px;
}

.run-cards {
  display: grid;
  grid-template-columns: repeat(5, minmax(190px, 1fr));
  gap: 10px;
}

.run-card {
  display: grid;
  gap: 10px;
  position: relative;
  overflow: hidden;
}

.run-card::before {
  content: "";
  position: absolute;
  inset: 0 0 auto 0;
  height: 3px;
  background: linear-gradient(90deg, var(--blue), var(--cyan), var(--amber));
}

.run-card h3 {
  margin: 0;
  font-size: 14px;
}

.run-card p {
  color: var(--muted);
  font-size: 13px;
  line-height: 1.4;
}

.run-meta {
  display: flex;
  gap: 6px;
  flex-wrap: wrap;
}

.run-meta span {
  border: 1px solid var(--line);
  border-radius: 999px;
  color: var(--muted);
  padding: 4px 7px;
  font-size: 11px;
}

pre {
  white-space: pre-wrap;
  word-break: break-word;
  min-height: 280px;
  margin: 0;
  background: #0e1113;
  border: 1px solid var(--line);
  border-radius: 8px;
  padding: 12px;
  color: #d7e0e4;
  overflow: auto;
}

.funnel-viz {
  display: grid;
  grid-template-columns: repeat(5, minmax(120px, 1fr));
  gap: 10px;
  margin-top: 12px;
}

.funnel-viz div {
  min-height: 80px;
  border: 1px solid var(--line);
  border-radius: 8px;
  background: #14181b;
  padding: 12px;
  display: grid;
  align-content: end;
  gap: 10px;
}

.funnel-viz span {
  display: block;
  height: 8px;
  border-radius: 999px;
  background: linear-gradient(90deg, var(--green), var(--cyan), var(--amber));
}

.funnel-viz strong {
  font-size: 13px;
}

.table-wrap {
  overflow-x: auto;
  margin-top: 12px;
}

table {
  width: 100%;
  border-collapse: collapse;
  min-width: 680px;
}

th,
td {
  border-bottom: 1px solid var(--line);
  padding: 10px;
  text-align: left;
}

th {
  color: var(--muted);
  font-size: 12px;
  font-weight: 600;
}

td {
  font-size: 13px;
}

.risk-card.warning {
  border-color: rgba(226, 184, 79, 0.42);
  background:
    linear-gradient(135deg, rgba(226, 184, 79, 0.12), transparent 52%),
    var(--surface-3);
}

.warning-line {
  margin-top: 12px;
  border: 1px solid rgba(73, 191, 212, 0.28);
  background: rgba(73, 191, 212, 0.08);
  color: #cdeef4;
  border-radius: 8px;
  padding: 11px 12px;
}

@media (max-width: 1200px) {
  .command-grid,
  .two-col,
  .metric-grid,
  .run-cards,
  .pipeline-details,
  .inventory-grid,
  .shard-grid,
  .mission-strip,
  .proof-grid,
  .funnel-viz {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .system-map {
    min-height: 560px;
  }

  .graph-workspace {
    grid-template-columns: 1fr;
  }

  .graph-inspector {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }

  .node-inspector {
    grid-column: span 2;
  }

  .map-lines {
    opacity: 0.68;
  }

  .map-node {
    min-width: 102px;
  }

  .n-agave { left: 5%; top: 10%; }
  .n-afxdp { left: 36%; top: 5%; }
  .n-decode { left: 66%; top: 12%; }
  .n-state { left: 10%; top: 35%; }
  .n-quote { left: 40%; top: 30%; }
  .n-owner { left: 68%; top: 38%; }
  .n-pm { left: 8%; top: 62%; }
  .n-tpu { left: 38%; top: 62%; }
  .n-public { left: 66%; top: 66%; }
  .n-reconcile { right: 5%; top: 82%; }
  .n-jito { right: 6%; top: 2%; }
  .n-inventory { left: 36%; bottom: 3%; }
}

@media (max-width: 560px) {
  .pipeline-topbar,
  .pipeline-panel .panel-head {
    padding-right: 0;
  }

  .capital-hud {
    position: static;
    width: 100%;
    max-height: none;
  }

  .capital-dropdown {
    position: static;
    width: 100%;
    max-height: none;
    margin-top: 8px;
    display: none;
  }

  .capital-hud.open .capital-dropdown {
    display: block;
  }

  .capital-list {
