    cadence.textContent = latency ? `${latency}ms` : `tick ${state.liveSequence}`;
    cadence.className = `status-token ${latency > 2800 ? "warn" : "ok"}`;
  }

  if (state.graph) state.graph.updateFromLive(data);
}

